/** Categories with every image resolved to a local .webp (src + width + height). */
export const productCategories = CATEGORIES.map((cat) => ({
  ...cat,
  image: images.products[cat.imageKey],
  items: cat.items.map((item) => ({
    ...item,
    image: images.products[item.imageKey]
  }))
}));

/** Flat list of all 13 products, each carrying its category metadata. */
export const allProducts = productCategories.flatMap((cat) =>
  cat.items.map((item) => ({
    ...item,
    categoryId: cat.id,
    categoryTitle: cat.title,
    categoryBadge: cat.badge,
    categoryImage: cat.image
  }))
);
